head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/calendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.contnId;
scwin.objTpCd;
scwin.vCurDate;
scwin.gLdMktTp = js_market;
scwin.vScrenID = "ULDSTF30401.xml";

//alert("js_bond_yn-->"+js_bond_yn);	
//2009.09.01 채권시장인 경우
if (js_bond_yn == "Y") {
    scwin.gLdMktTp = "4";
}

//alert("gLdMktTp-->"+gLdMktTp);

$c.stf.showObj(pnl_kclic, false);
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_single_read = function() {
    //공지사항 개별조회

    trs_Read.Action = "/NoticeContent.do?method=readNoticeContent&CONTN_ID=" + scwin.contnId + "&objTpCd=" + scwin.objTpCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_NoticeContentSingle,O:pOutput2=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_update = function() {
    //공지사항 수정

    //이메일 필수입력 제거(YSH, 2008/08/25)
    /*
    if(tbox_email.value=="" || tbox_email.value.indexOf(" ") == "" ) {
    	alert( getMessageParam("MSG-A005", "이메일") );
    	tbox_email.focus();
    	return;
    }
    */
    if ("" != tbox_email.getValue()) {
        var a = tbox_email.getValue().indexOf('@');
        if (a <= 0 || a == tbox_email.getValue().length - 1) {
            $c.win.alert("Email은 [id@krx.co.kr] 등의 형태로 입력하셔야 합니다.");
            tbox_email.setValue("");
            tbox_email.focus();
            return;
        }
    }
    if (!scwin.checkMaxLength1(tbox_email, 100, "이메일")) {
        tbox_email.setValue("");
        tbox_email.focus();
        return false;
    }
    if (scwin.objTpCd == "1") {
        if (rdo_mkt_gubun.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "시장구분"));
            rdo_mkt_gubun.focus();
            return;
        }
    }
    if (tbox_password.getValue() == "" || tbox_password.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "비밀번호"));
        tbox_password.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_password, 30, "비밀번호")) {
        tbox_password.setValue("");
        tbox_password.focus();
        return false;
    }
    if (dts_NoticeContentSingle.getCellData(dts_NoticeContentSingle.getRowPosition(), "PW") != tbox_password.getValue()) {
        $c.win.alert("[비밀번호]를 잘못 입력하셨습니다.");
        tbox_password.setValue("");
        tbox_password.focus();
        return;
    }
    if (edt_SDate.getValue() == "" || edt_SDate.Text.indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "게시물적용시작일자"));
        edt_SDate.focus();
        return;
    }
    if (scwin.fn_dateCheck() == false) {
        return;
    }
    //if(tbox_title.value=="" || tbox_title.value.indexOf(" ") == "" ) {
    if (tbox_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_title, 200, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }

    //if(tarea_content.Text =="" || tarea_content.Text.indexOf(" ") == "" ) {
    if (tarea_content.Text == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_content.Focus();
        return;
    }
    if (!scwin.checkMaxLength2(tarea_content, 2000, "내용")) {
        tarea_content.text = "";
        tarea_content.focus();
        return false;
    }
    var rtn = confirm('위사항을 수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        if (scwin.objTpCd == "1") {
            //2009.09.01 채권공시 관련 추가
            if (js_bond_yn == "Y") {
                dts_NoticeContentSingle.setCellData(dts_NoticeContentSingle.getRowPosition(), "LD_MKT_TP_CD", "4");
            } else {
                dts_NoticeContentSingle.setCellData(dts_NoticeContentSingle.getRowPosition(), "LD_MKT_TP_CD", rdo_mkt_gubun.getValue());
            }
        }

        //조회(영문)일 , 밸류업일 경우 bbs_tp_cd = 61 이다
        if (scwin.objTpCd == 'D') {
            dts_NoticeContentSingle.setCellData(dts_NoticeContentSingle.getRowPosition(), "BBS_TP_CD", "61");
        }

        // 적용 끝일자가 없으면 자동으로 99991231 입력한다.
        if (edt_EDate.getValue() == "") {
            dts_NoticeContentSingle.setCellData(1, "NOTI_END_DD", "99991231");
        }
        dts_NoticeContentSingle.setCellData(1, "CHRG_INST_ID", $c.stf.getObjectValue(cmb_chrg_inst));
        trs_Update.Action = "/NoticeContent.do?method=modifyNoticeContent&CONTN_ID=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Update.KeyName = "toinb_dataid4";
        trs_Update.KeyValue = "JSP(I:pInput1=dts_NoticeContentSingle,I:pInput2=dts_fileList)";
        trs_Update.Post();
    }
};
scwin.fn_save = function() {
    //공지사항 등록

    if (check1.checked == false &&
        check2.checked == false &&
        check3.checked == false &&
        check4.checked == false &&
        check5.checked == false &&
        check6.checked == false) {
        $c.win.alert("[공지대상 시스템]을 선택해주세요");
        return;
    }
    if (check3.checked == true || check4.checked == true || check5.checked == true) {
        if (rdo_mkt_gubun.getValue() == "") {
            $c.win.alert("[공지대상 시스템]이 제출(국문/영문), K-CLIC 일경우 [시장구분]을 선택해주세요");
            rdo_mkt_gubun.focus();
            return;
        }
    }
    if (check5.checked == true) {
        var ChrgInstId = $c.cp.valueOfIndex(cmb_chrg_inst, "VALUE", cmb_chrg_inst.getSelectedIndex());
        if (ChrgInstId == "") {
            $c.win.alert("[공지대상 시스템]이 K-CLIC 일경우 담당기관을 선택해주세요");
            cmb_chrg_inst.focus();
            return;
        } else {
            dts_noticeInfo.setCellData(1, "CHRG_INST_ID", ChrgInstId);
        }
    }
    if (check6.checked == true) {
        //조회(영문)
        if (check5.checked == true || check4.checked == true || check3.checked == true || check2.checked == true || check1.checked == true) {
            $c.win.alert("[공지대상 시스템]이 조회(영문)일 경우 다른 시스템과 함께 사용할 수 없습니다. ");
            return;
        }
    }
    if (check1.checked == true) {
        //조회(국문) -- 밸류업
        if ($c.stf.getObjectValue(rdo_bbs_tp_cd) == "60") {
            if (check6.checked == true || check5.checked == true || check4.checked == true || check3.checked == true || check2.checked == true) {
                $c.win.alert("[공지대상 시스템]이 조회(국문)이면서 밸류업일 경우 다른 시스템과 함께 사용할 수 없습니다. ");
                return;
            }
        }
    }
    //이메일 필수입력 제거 (YSH, 2008/08/25)
    /*
    if(tbox_email.value=="" || tbox_email.value.indexOf(" ") == "" ) {
    	alert( getMessageParam("MSG-A005", "이메일") );
    	tbox_email.focus();
    	return;
    }
    */
    if ("" != tbox_email.getValue()) {
        var a = tbox_email.getValue().indexOf('@');
        if (a <= 0 || a == tbox_email.getValue().length - 1) {
            $c.win.alert("Email은 [id@krx.co.kr] 등의 형태로 입력하셔야 합니다.");
            tbox_email.setValue("");
            tbox_email.focus();
            return;
        }
    }
    if (!scwin.checkMaxLength1(tbox_email, 100, "이메일")) {
        tbox_email.setValue("");
        tbox_email.focus();
        return false;
    }
    if (tbox_password.getValue() == "" || tbox_password.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "비밀번호"));
        tbox_password.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_password, 30, "비밀번호")) {
        tbox_password.setValue("");
        tbox_password.focus();
        return false;
    }
    if (edt_SDate.getValue() == "" || edt_SDate.Text.indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "게시물적용시작일자"));
        edt_SDate.focus();
        return;
    }
    if (scwin.fn_dateCheck() == false) {
        return;
    }
    //if(tbox_title.value=="" || tbox_title.value.indexOf(" ") == "" ) {
    if (tbox_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_title, 200, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }

    //if(tarea_content.Text =="" || tarea_content.Text.indexOf(" ") == "" ) {
    if (tarea_content.Text == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_content.Focus();
        return;
    }
    if (!scwin.checkMaxLength2(tarea_content, 2000, "내용")) {
        tarea_content.text = "";
        tarea_content.focus();
        return false;
    }
    var rtn = confirm('위사항을 입력 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        //공시배포
        if (check1.checked == true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN1", "Y");
        }
        //공시제출(국문)
        if (check2.checked == true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN2", "Y");
        }
        //공시처리
        if (check3.checked == true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN3", "Y");
        }

        //공시제출(영문)
        if (check4.checked == true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN4", "Y");
        }
        //K-CLIC
        if (check5.checked == true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN5", "Y");
        }

        //조회(영문)
        if (check6.checked == true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN6", "Y");
            dts_noticeInfo.setCellData(1, "BBS_TP_CD", "61");
        }

        //뒷부분 공백 제거  (YSH, 2008/08/25)
        var passStr = dts_noticeInfo.getCellData(1, "PW");
        dts_noticeInfo.setCellData(1, "PW", $c.ut.trim(passStr));
        //alert(dts_noticeInfo.NameValue(1,"PW"));

        // 적용 끝일자가 없으면 자동으로 99991231 입력한다.
        if (edt_EDate.getValue() == "") {
            dts_noticeInfo.setCellData(1, "NOTI_END_DD", "99991231");
        }

        //2009.09.01 채권공시 관련 추가
        if (js_bond_yn == "Y") {
            dts_noticeInfo.setCellData(1, "LD_MKT_TP_CD", "4");
        }
        trs_Save.Action = "/NoticeContent.do?method=registerNoticeContent" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_noticeInfo,I:pFile1=dts_fileList)";
        trs_Save.Post();
    }
};
scwin.fn_delete = function() {
    //공지사항 삭제

    if (dts_NoticeContentSingle.getCellData(1, "PW") != tbox_password.getValue()) {
        $c.win.alert("[비밀번호]를 잘못 입력하셨습니다.");
        return false;
    }
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        //dts_NoticeDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_NoticeDelete.insertRow();
        dts_NoticeDelete.setCellData(1, "CONTN_ID", scwin.contnId);
        dts_NoticeDelete.setCellData(1, "NOTI_OBJ_SYS_TP_CD", scwin.objTpCd);
        dts_NoticeDelete.setCellData(1, "BBS_TP_CD", dts_NoticeContentSingle.getCellData(dts_NoticeContentSingle.getRowPosition(), "BBS_TP_CD"));
        trs_Delete.Action = "/NoticeContent.do?method=removeNoticeContent" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput=dts_NoticeDelete)";
        trs_Delete.Post();
    }
};
scwin.fn_SetIrInfoHeader = function() {
    // CUD용 Header
    dts_noticeInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NOTICECONTENT_NOTEINFO_INOUT";
    dts_noticeInfo.Reset();
    dts_noticeInfo.insertRow();
};

//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?file_id=" + scwin.contnId + "&attach_seq=" + attach_seq + "&gubun=2";
};
scwin.fn_dateCheck = function() {
    /*
    if((vCurDate > parseInt(edt_SDate.Text,'10') ) ||(vCurDate > parseInt(edt_EDate.Text,'10'))) {
        alert("[게시물적용기간을]현재일이후로 입력하세요");return false;
    } else 
    */ //게시물적용일자 체크 해제 (YSH, 2008/08/25)
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        $c.win.alert("[게시물적용기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        return false;
    }
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};


//2017-02-13 KBoY FileSizeLimit 30MB		
scwin.canUploadFile = function() {
    var maxFileSize = 1024 * 1024 * 30; //30MB		
    var mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};



//20250718 파일 확장자 체크 로직
scwin.fn_CheckExtension = function(fileNm) {
    var fileExts = new Array(".hwp", ".docx", ".doc", ".xls", ".xlsx", ".ppt", ".pptx", ".pdf", ".gif", ".jpg", ".jpeg", ".bmp", ".tif", ".txt", ".drt", ".dsd", ".png", ".zip"); // 허가 확장자 목록
    var vsFileNm = fileNm;
    var vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    var vsFlag = true;
    var ext = fileNm.substr(fileNm.lastIndexOf(".")).toLowerCase();
    for (var i = 0; i < fileExts.length; i++) {
        if (fileExts[i] == vsFileExts || fileExts[i] == ext) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        $c.win.alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};


//20250718
scwin.showAlertMsg = function(msg) {
    if (msg.indexOf('50014') != -1) {
        $c.win.alert('첨부하려는 파일을 열어놓은 경우, 파일 첨부가 불가능 합니다.\r\n첨부하려는 파일을 닫고 다시 진행하시기 바랍니다.');
    } else {
        $c.win.alert(msg);
    }
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_save_onclick = function() {
    if (scwin.contnId == "input") {
        scwin.fn_save();
    } else {
        scwin.fn_update();
    }
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "공지사항등록"));
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "공지사항등록"));
    scwin.showAlertMsg(trs_Save.ErrorMsg);
};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "공지사항수정"));
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "공지사항수정"));
    scwin.showAlertMsg(trs_Update.ErrorMsg);
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "공지사항삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "공지사항삭제"));
    scwin.showAlertMsg(trs_Delete.ErrorMsg);
};
scwin.btn_lineadd_onclick = function() {
    if (dts_fileList.getTotalRow() == 5) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        var vFile = inf_find.getValue();
        var vFileNm = vFile.split("\\");
        vFileNm = vFileNm[vFileNm.length - 1];
        if (vFileNm != "") {
            if (scwin.fn_CheckExtension(vFileNm)) {
                $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
                return;
            }
        }
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
    if (!scwin.canUploadFile()) {
        $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
        return;
    }
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.getValue();
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_userlist_OnClick = function(row, colid) {
    if (row == 0) return;
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.gform_onload = function() {
    // 영문공시제출 오픈시 아래 부분 삭제
    //--------------------------------------------------
    $c.stf.showObj(label_28, false);
    $c.stf.showObj(pnl_eng_fil, false);
    //----------------------------------------------------

    $c.cm.PanelToGroupBox(panel_Top);
    scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
    getContnId = $c.frame.path("../").fn_getContnId;
    scwin.contnId = getContnId();
    if (scwin.contnId != "input") {
        getSysCode = $c.frame.path("../").fn_getSysCode;
        scwin.objTpCd = getSysCode();
        $c.stf.showObj(panel_mkt_gubun, false);
        if (scwin.objTpCd == "조회(국문)") {
            scwin.objTpCd = "2";
            $c.stf.showObj(panel_sel1, false);
            $c.stf.showObj(panel_sel2, true);
            $c.stf.showObj(panel_sel3, false);
            $c.stf.showObj(panel_sel6, false);
            $c.stf.showObj(panel_sel7, false);
            $c.stf.showObj(panel_sel8, false);
            $c.stf.showObj(pnl_valueup, true);
            rdo_bbs_tp_cd.setDisabled(true);
        } else if (scwin.objTpCd == "처리시스템") {
            scwin.objTpCd = "3";
            $c.stf.showObj(panel_sel1, false);
            $c.stf.showObj(panel_sel2, false);
            $c.stf.showObj(panel_sel3, true);
            $c.stf.showObj(panel_sel6, false);
            $c.stf.showObj(panel_sel7, false);
            $c.stf.showObj(panel_sel8, false);
            if (scwin.gLdMktTp == '9') $c.stf.showObj(panel_mkt_gubun, true);
        } else if (scwin.objTpCd == "제출(영문)시스템") {
            scwin.objTpCd = "6";
            $c.stf.showObj(panel_sel1, false);
            $c.stf.showObj(panel_sel2, false);
            $c.stf.showObj(panel_sel3, false);
            $c.stf.showObj(panel_sel6, true);
            $c.stf.showObj(panel_sel7, false);
            $c.stf.showObj(panel_sel8, false);
            if (scwin.gLdMktTp == '9') $c.stf.showObj(panel_mkt_gubun, true);
        } else if (scwin.objTpCd == "K-CLIC시스템") {
            scwin.objTpCd = "B";
            $c.stf.showObj(panel_sel1, false);
            $c.stf.showObj(panel_sel2, false);
            $c.stf.showObj(panel_sel3, false);
            $c.stf.showObj(panel_sel6, false);
            $c.stf.showObj(panel_sel7, true);
            $c.stf.showObj(panel_sel8, false);
            if (scwin.gLdMktTp == '9') $c.stf.showObj(panel_mkt_gubun, true);
        } else if (scwin.objTpCd == "조회(영문)") {
            scwin.objTpCd = "D";
            $c.stf.showObj(panel_sel1, false);
            $c.stf.showObj(panel_sel2, false);
            $c.stf.showObj(panel_sel3, false);
            $c.stf.showObj(panel_sel6, false);
            $c.stf.showObj(panel_sel7, false);
            $c.stf.showObj(panel_sel8, true);
            if (scwin.gLdMktTp == '9') {
                $c.stf.showObj(panel_mkt_gubun, true);
                rdo_mkt_gubun.setDisabled(true);
            }
            $c.stf.showObj(pnl_valueup, true);
            rdo_bbs_tp_cd.setDisabled(true);
        } else {
            scwin.objTpCd = "1";
            $c.stf.showObj(panel_sel1, true);
            $c.stf.showObj(panel_sel2, false);
            $c.stf.showObj(panel_sel3, false);
            $c.stf.showObj(panel_sel6, false);
            $c.stf.showObj(panel_sel7, false);
            $c.stf.showObj(panel_sel8, false);
            if (scwin.gLdMktTp == '9') $c.stf.showObj(panel_mkt_gubun, true);
        }
        scwin.fn_single_read();
        $c.stf.showObj(gubun, false);
        //showObj(panel_mkt_gubun,false);

        if (scwin.objTpCd == "1" || scwin.objTpCd == "6") {
            //showObj(panel_mkt_gubun,false);
            rdo_mkt_gubun.setValue(dts_NoticeContentSingle.getCellData(dts_NoticeContentSingle.getRowPosition(), "LD_MKT_TP_CD"));
        }
        $c.stf.setObjectValue(cmb_chrg_inst, dts_NoticeContentSingle.getCellData(dts_NoticeContentSingle.getRowPosition(), "CHRG_INST_ID"));
    } else {

        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        scwin.fn_SetIrInfoHeader();
        //edt_SDate.text = cGetToday("yyyymmdd");
        $c.stf.showObj(panel_sel1, false);
        $c.stf.showObj(panel_sel2, false);
        $c.stf.showObj(panel_sel3, false);
        $c.stf.showObj(panel_mkt_gubun, false);
        if (js_market == '9') {
            $c.stf.showObj(panel_mkt_gubun, true);
        }
        $c.stf.showObj(btn_delete, false);
        var today = $c.ut.cGetToday2();
        var nextMonDay = $c.ut.calcMonth(today, 1);
        edt_EDate.setValue(""); //"99991231";

        var mkt_nm = "";
        //mkt_nm = (js_market == "1") ? "(유)" : "(코)";		

        //2009.09.01 채권공시관련
        if (js_bond_yn == "Y") {
            mkt_nm = "(채)";
        } else if (js_market == "1") {
            mkt_nm = "(유)";
        } else if (js_market == "2") {
            mkt_nm = "(코)";
        }
        tbox_user.setValue(mkt_nm + js_dep_nm);
        dts_noticeInfo.setCellData(dts_noticeInfo.getRowPosition(), "WRTR_EMP_NO", js_emp_no);
        if (js_market == "9") {
            $c.stf.setObjectValue(rdo_mkt_gubun, "9");
        } else {
            $c.stf.setObjectValue(rdo_mkt_gubun, js_market);
        }
        $c.stf.showObj(pnl_valueup, false);
        $c.stf.setObjectValue(rdo_bbs_tp_cd, "03");
        rdo_bbs_tp_cd.setDisabled(true);
    }
};
scwin.rdo_bbs_tp_cd_OnSelChange = function() {
    if (rdo_bbs_tp_cd.getValue() == "60") {
        $c.stf.setObjectValue(rdo_mkt_gubun, "9");
        $c.stf.showObj(panel_mkt_gubun, true);
        rdo_mkt_gubun.setDisabled(true);
    } else {
        if (scwin.contnId != "input") {

        } else {
            if (js_market == "9") {
                $c.stf.showObj(panel_mkt_gubun, true);
                rdo_mkt_gubun.setDisabled(false);
                $c.stf.setObjectValue(rdo_mkt_gubun, "9");
            } else {
                $c.stf.setObjectValue(rdo_mkt_gubun, js_market);
            }
        }
    }
};
scwin.check6_onclick = function() {
    //조회(영문) - 밸류업만 가능
    if (check6.checked == true) {
        $c.stf.showObj(panel_mkt_gubun, false);
        $c.stf.setObjectValue(rdo_mkt_gubun, "9");
        $c.stf.showObj(pnl_valueup, true);
        $c.stf.setObjectValue(rdo_bbs_tp_cd, "60");
        rdo_bbs_tp_cd.setDisabled(true);
        if (check1.checked == true || check2.checked == true || check3.checked == true || check4.checked == true || check5.checked == true) {
            $c.win.alert("조회(영문)시스템은 다른 시스템과 같이 사용할 수 없습니다.");
        }
        check1.setValue(0);
        check2.setValue(0);
        check3.setValue(0);
        check4.setValue(0);
        check5.setValue(0);
        check1.setDisabled(true);
        check2.setDisabled(true);
        check3.setDisabled(true);
        check4.setDisabled(true);
        check5.setDisabled(true);
    } else {
        check1.setDisabled(false);
        check2.setDisabled(false);
        check3.setDisabled(false);
        check4.setDisabled(false);
        check5.setDisabled(false);
        $c.stf.showObj(pnl_valueup, false);
        rdo_bbs_tp_cd.setDisabled(true);
        $c.stf.setObjectValue(rdo_bbs_tp_cd, "03");
    }
};
scwin.check5_onclick = function() {
    if (scwin.gLdMktTp == '9') {
        if (check2.checked == true || check3.checked == true || check4.checked == true || check5.checked == true) {
            $c.stf.showObj(panel_mkt_gubun, true);
        } else {
            $c.stf.showObj(panel_mkt_gubun, false);
        }
    }
    if (check5.checked == true) {
